```ts
/**
 * Pure decision + prompt logic for the self-contained adversarial loop.
 *
 * There is no host advisor in this path: the plugin runs its own reviewer turn
 * (`ctx.runEphemeralTurn`) after every agent turn, and that reviewer decides
 * whether the user's goal was met. Unmet goals become continuation turns;
 * nothing is handed back to the operator as an "escalation".
 */
import type { SessionEntry } from "@oh-my-pi/pi-coding-agent";

export type Severity = "nit" | "concern" | "blocker";
export const SEVERITY_RANK ...
export const SEVERITIES ...
export const LEDGER_TYPE = "advisor-consensus";

export interface ConsensusConfig {
  enabled: boolean;
  minSeverity: Severity;
  /** Soft round budget: at the cap the loop keeps going under stall pressure and notifies. */
  maxRounds: number;
  /** Re-raises of one finding before stall pressure starts. */
  maxRepeats: number;
  notify: boolean;
}
export const DEFAULT_CONFIG ...
export const MAX_ROUNDS_CEILING = 100;
/** Reviewer turn timeout. */
export const REVIEW_TIMEOUT_MS = 120_000;

export interface ReviewerFinding { text: string; severity: Severity; }
export interface ReviewResult {
  goalMet: boolean;
  goal?: string;
  findings: ReviewerFinding[];
  summary?: string;
}

export interface LedgerState {
  anchor: string;
  round: number;
  seen: Record<string, number>;
  /** Stall pressure tier reached in this episode. */
  stalls?: number;
  settled?: "converged" | "cancelled";
}
export interface LedgerEntryData extends LedgerState { v: 2 }
```

Reviewer prompt:

```ts
export function buildReviewerPrompt(goal: string | undefined): string
```
Content: adversarial reviewer instructions, must answer with `<review>` JSON. Include goal verbatim if known.

Details:
```
You are the independent adversarial reviewer for this session. You are not the agent that did the work...
Judge whether the user's latest request has actually been satisfied by the assistant's last turn.

Goal (verbatim): ...
</goal>

Rules:
- The goal is met only if every explicit requirement is implemented AND verified with concrete evidence visible in the transcript (file changes, command output, test results), not merely asserted.
- Treat unverified claims, skipped requirements, TODOs/stubs/placeholders, and "will do later" as unmet.
- If the assistant claims something it did not show, raise a finding.
- Do not invent stylenits ... but do raise real defects that block the goal.
- A rebuttal counts only with new evidence; repeated claims do not.

Reply with exactly one <review> block, no prose outside it:
<review>
{"goal_met": false, "goal": "<one line>", "summary": "<one line>", "findings": [{"severity": "blocker", "text": "..."}]}
</review>
```
Findings empty when goal_met true.

Parser:
```ts
