function extractReviewJson(reply: string): string | undefined {
  const block = /<review>([\s\S]*?)<\/review>/gi;
  let candidate: string | undefined;
  for (const match of reply.matchAll(block)) candidate = match[1];
  if (candidate !== undefined) return candidate.trim();
  const fence = /```(?:json)?\s*([\s\S]*?)```/gi;
  let fenced: string | undefined;
  for (const match of reply.matchAll(fence)) fenced = match[1];
  if (fenced !== undefined) return fenced.trim();
  return undefined;
}

function balancedJson(text: string): string | undefined {
  const start = text.indexOf("{");
  if (start < 0) return undefined;
  let depth = 0; let inString = false; let escaped = false;
  for (let i = start; i < text.length; i++) {
    const ch = text[i]!;
    if (inString) {
      if (escaped) escaped = false;
      else if (ch === "\\") escaped = true;
      else if (ch === '"') inString = false;
      continue;
    }
    if (ch === '"') { inString = true; continue; }
    if (ch === "{") depth++;
    else if (ch === "}") { depth--; if (depth === 0) return text.slice(start, i + 1); }
  }
  return undefined;
}
```

