const handleStopDecision = (...) => { if ignore return; if converged settle; else record; }
```
Actually applyReviewForStop can just:
```ts
const decision = decideAtStop(...);
if (decision.kind === "ignore") return decision;
if (decision.kind === "converged") { settleConverged(...); return decision; }
recordRound(...);
if (state.stopHookRounds < STOP_HOOK_ROUNDS) { state.stopHookRounds++; }
else state.pendingRound = decision;
return decision;
