```ts
export function decideAtStop(input: { ...; allowReopen?: boolean }): StopDecision {
	const { entries, config, lastAssistant, review } = input;
	...
	if (active?.settled && !(input.allowReopen === true && active.settled === "converged")) {
		return { kind: "ignore", reason: "settled", round };
	}
	if (!review) return ...

	const reviewerFindings = review.findings.filter(...);
	const advisorFindings = config.includeAdvisor
		? pendingAdvisorFindings(entries, scan).filter(f => meetsMinSeverity(f.severity, config.minSeverity))
		: [];
