const CATCH_UP_WINDOW_MS = 10*60_000;
const CATCH_UP_DELAY_MS = 250;

const catchUpLateNote = async (ctx) => {
  if (ctx.agent.kind !== "main") return;
  const state = stateFor(sessionId);
  const config = effectiveConfig(ctx.cwd, state);
  if (!config.enabled || !config.includeAdvisor || state.paused) return;
  if (state.endedAt === undefined || Date.now() - state.endedAt > CATCH_UP_WINDOW_MS) return;
  if (ctx.sessionModes?.getState().plan.status === "active") return;
  if (!ctx.isIdle() || ctx.hasPendingMessages()) return;
  if (state.reviewing) return;
  ... refreshAdvisorState, pin sync, sync model ...
  const entries = ctx.sessionManager.getBranch();
  state.reviewing = true;
  let review;
  try { review = await runReview(ctx, state); } finally { state.reviewing = false; }
  if (!review) return;
  const decision = decideAtStop({entries, config, lastAssistant: lastAssistantAnswer(entries), review, allowReopen: true});
  if (decision.kind !== "continue") return;  // ignore or already converged: nothing to reopen
  if (config.notify) ctx.ui.notify(`advisor-consensus: late advisor finding reopened round ${decision.round}/${config.maxRounds}`, "warning");
  recordRound(ctx, state, config, decision);
  steerRound(state, config, decision);
};
